import fs from 'node:fs';
global.window = {};
await import('/home/runner/work/PlayGround/PlayGround/js/story.js');
const { scenes, start, resolveEnding } = window.STORY;
const q = [{ id: start, affection: 0, trust: 0, flags: {}, path: [], mem: [] }];
const seen = new Set();
const finals = [];
while (q.length) {
  const s = q.shift();
  const key = s.id + '|' + s.affection + '|' + s.trust + '|' + (s.flags.finalRoute || '');
  if (seen.has(key)) continue;
  seen.add(key);
  const n = scenes[s.id];
  if (!n) continue;
  if (n.endingResolve) { finals.push({ ...s, ending: resolveEnding(s) }); continue; }
  if (n.ending) continue;
  if (n.choices) {
    for (const c of n.choices) {
      q.push({ id: c.next, affection: Math.min(30, s.affection + (c.affection || 0)), trust: Math.min(12, s.trust + (c.trust || 0)), flags: { ...s.flags, ...(c.flags || {}) }, path: [...s.path, c.label], mem: n.memory ? [...s.mem, n.memory.id] : s.mem });
    }
    continue;
  }
  if (n.next) q.push({ ...s, id: n.next, mem: n.memory ? [...s.mem, n.memory.id] : s.mem });
}
const pick = (e, sort) => finals.filter(f => f.ending === e).sort(sort)[0];
const out = {
  true: pick('true', (a, b) => b.affection - a.affection || b.trust - a.trust),
  good: pick('good', (a, b) => a.affection - b.affection || a.trust - b.trust),
