page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(900);
await page.evaluate(() => localStorage.clear());
await page.evaluate(() => localStorage.setItem('byeol-night-settings-v1', JSON.stringify({ speed: 2, muted: true, shake: false })));
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(900);

const clickCard = async () => {
  await page.locator('#dialogueCard').click({ position: { x: 30, y: 30 } }).catch(() => {});
  await page.waitForTimeout(90);
};
const openMenu = async () => {
  await page.locator('#menuBtn').click();
  await page.waitForTimeout(300);
};
const closePanel = async () => {
  await page.locator('.panel.show [data-close]').first().click().catch(() => {});
  await page.waitForTimeout(300);
};
const ensureTitle = async () => {
  if (await page.locator('#endingScreen').isVisible().catch(() => false)) {
    await page.locator('#endingTitleBtn').click();
    await page.waitForTimeout(900);
  }
  if (!(await page.locator('#titleScreen').isVisible().catch(() => false))) {
    await page.evaluate(() => { document.getElementById('game').dataset.screen = 'title'; document.getElementById('titleScreen').classList.remove('is-hidden'); });
    await page.waitForTimeout(400);
  }
};

const results = {};
let first = true;
for (const key of ['true', 'good', 'normal', 'sad']) {
  const route = paths[key];
  await ensureTitle();
  await page.getByRole('button', { name: 'Play game' }).click();
  await page.waitForTimeout(350);
  let ci = 0;
  let guard = 0;
  let saveLoad = null;

  if (first) {
    // finish first line, then manually save and verify restoration
    await clickCard();
    await page.waitForTimeout(250);
    const savedText = norm(await page.locator('#dialogueText').textContent());
    await openMenu();
    await page.locator('#saveBtn').click();
    await page.waitForTimeout(500);
    await clickCard(); await page.waitForTimeout(180);
    await clickCard(); await page.waitForTimeout(350);
    const advancedText = norm(await page.locator('#dialogueText').textContent());
    await openMenu();
    await page.locator('#loadBtn').click();
    await page.waitForTimeout(900);
    const loadedText = norm(await page.locator('#dialogueText').textContent());
    saveLoad = { savedText, advancedText, loadedText, ok: savedText === loadedText && savedText !== advancedText };

    // history, gallery, settings panel checks
    await openMenu();
    await page.locator('#historyBtn').click();
    await page.waitForTimeout(350);
    const historyCount = await page.locator('.history-entry').count();
    await closePanel();
    await openMenu();
    await page.locator('#galleryMenuBtn').click();
    await page.waitForTimeout(300);
    const galleryCards = await page.locator('.memory-card').count();
    const galleryUnlocked = await page.locator('.memory-card.unlocked').count();
    await closePanel();
    await openMenu();
    await page.locator('#settingsMenuBtn').click();
    await page.waitForTimeout(300);
    const settingRows = await page.locator('.setting-row').count();
    await closePanel();
    // keyboard: Esc opens menu, Esc closes
    await page.keyboard.press('Escape');
    await page.waitForTimeout(250);
    const menuByEsc = await page.locator('#menuPanel').isVisible();
    await page.keyboard.press('Escape');
    await page.waitForTimeout(250);
    saveLoad.panels = { historyCount, galleryCards, galleryUnlocked, settingRows, menuByEsc };
    console.log('save/load + panels', JSON.stringify(saveLoad));
    first = false;
  }

  while (guard++ < 700) {
    if (await page.locator('#endingScreen').isVisible().catch(() => false)) break;
    const buttons = page.locator('.choice-btn:visible');
    const count = await buttons.count();
    if (count) {
      const labels = (await buttons.locator('.choice-label').allTextContents()).map(norm);
      const want = norm(route.path[ci]);
      let idx = labels.indexOf(want);
      if (idx < 0) idx = labels.findIndex((l) => l.includes(want.slice(0, 14)) || want.includes(l.slice(0, 14)));
      if (idx < 0) throw new Error(`route ${key}: choice ${ci} not found\nwant: ${want}\nlabels: ${labels.join(' | ')}`);
      await buttons.nth(idx).click();
      ci++;
      await page.waitForTimeout(170);
      continue;
    }
    await clickCard();
  }
  await page.waitForTimeout(1900);
  const actual = {
    kicker: (await page.locator('#endingKicker').textContent()).trim(),
    title: (await page.locator('#endingTitle').textContent()).trim(),
    affection: (await page.locator('#endAffection').textContent()).trim(),
    trust: (await page.locator('#endTrust').textContent()).trim(),
    memories: (await page.locator('#endMemories').textContent()).trim(),
    count: (await page.locator('#endingCount').textContent()).trim(),
    collection: (await page.locator('#endingCollection').textContent()).trim(),
    choices: ci
  };
  const ok = actual.kicker === expected[key].kicker && actual.title === expected[key].title && ci === route.path.length;
  results[key] = { ok, actual, expected, saveLoad };
  console.log(`[${ok ? 'PASS' : 'FAIL'}] ${key}`, JSON.stringify(actual));
  await page.screenshot({ path: `screenshots/ending-${key}-e2e.png` });
}

// final persistence check
const stored = await page.evaluate(() => JSON.parse(localStorage.getItem('byeol-night-endings-v1') || '[]'));
console.log('endings stored', stored);
console.log('errors', errors);
console.log('ALL PASS', Object.values(results).every(r => r.ok) && stored.length === 4 && errors.length === 0);
fs.writeFileSync('/tmp/opencode/e2e-results.json', JSON.stringify({ results, stored, errors }, null, 2));
await browser.close();
